int[] a = {1, 3, 5, 7, 9, 11};
int lo = 0, hi = 5, target = 11;
while (lo <= hi) {
    int mid = (lo + hi) / 2;
    if (a[mid] == target) { System.out.println("found " + mid); break; }
    if (a[mid] < target) lo = mid + 1; else hi = mid - 1;
}

